let font;
let hbStr = "∞♥∞✝∞♀∞♂∞☺"; // human being
let hbCol = ["purple", "red", "purple", "darkblue", "purple", "pink", "purple", "lightblue", "purple", "yellow"];
let morph;
const morphFrames = 180;
const fps = 60;

function preload() {
	font = loadFont('https://openprocessing.org/sketch/1960809/files/MPLUS1p-Medium.ttf');
}

function setup() {
	createCanvas(windowWidth, windowHeight);
	pixelDensity(1);
	loop();
	stroke(222);
	strokeWeight(4);
	frameRate(fps);

	if (hbStr.length != hbCol.length) {
		console.log(">Error: hbStr and hbCol have different length " + hbStr.length + ", " + hbCol.length)
	}

	morph = [];
	for (let i = 0; i < hbStr.length; i++) {
		morph.push(createMorphArray(hbStr.charAt(i)));
		// console.log("" + morph[morph.length - 1].length)
	}
}

function windowResized() {
	setup();
}

// one time creation of particles
function createMorphArray(str) {
	let margin = max(width, height) * 0.1
	let res = [];
	let points;
	let bounds;

	push();
	textFont(font);
	textAlign(LEFT, TOP);

	// Array: an array of points, each with x, y, alpha(window.color(the path angle))
	points = font.textToPoints(str, 0, 0, 10, {
		sampleFactor: sqrt(width * height) * 0.014,
		simplifyThreshold: 0
	});
	bounds = font.textBounds(str, 0, 0, 10);
	// console.log("bounds x,y,w,h = " + bounds.x + ", " + bounds.y + ", " + bounds.w + ", " + bounds.h + ", ")
	pop();

	let minX = Infinity,
		maxX = -Infinity,
		minY = Infinity,
		maxY = -Infinity;
	for (let p of points) {
		if (p.x < minX) minX = p.x;
		if (p.x > maxX) maxX = p.x;
		if (p.y < minY) minY = p.y;
		if (p.y > maxY) maxY = p.y;
	}
	const bW = maxX - minX;
	const bH = maxY - minY;

	const ar_x = (width - 2 * margin) / bW; // bounds.w;
	const ar_y = (height - 2 * margin) / bH; // bounds.h;
	let xOff = margin;
	let yOff = margin;
	let ar;
	if (ar_x >= ar_y) {
		ar = ar_y
		xOff = margin + (width - 2 * margin - bW * ar) * 0.5;
	} else {
		ar = ar_x
		yOff = margin + (height - 2 * margin - bH * ar) * 0.5;
	}

	for (let p of points) {
		const x = (p.x - minX) * ar + xOff;
		const y = (p.y - minY) * ar + yOff;
		res.push({
			x,
			y
		});
	}

	return res;
}


function mousePressed() {
	if (mouseButton === LEFT) {
		if (isLooping()) {
			// noLoop() removed for animation
		} else {
			loop();
		}
	}
}

function getMorphProgress(delta = 0) {
	var res = (frameCount + delta)/morphFrames - floor(frameCount/morphFrames);
	// console.log(res);
	return res;
}

// periodic drawing
function draw() {
	background(0, 0, 8, 128);

	drawBack();

	push();
	translate(width*0.5, height*0.5);
	// rotate(frameCount * 0.04);
	// rotate((noise(frameCount * 0.02) - 0.5) * HALF_PI); // like the conceptional idea about faster and slower, but visulization looks odd
	scale(sin(frameCount/fps + HALF_PI), 1); // scale X only, simulate rotateX in 2D
	translate(-width*0.5, -height*0.5);

	drawCurrentState()
	drawNextState()
	pop();

	// morphing will be out of the scaling = rotation effect
	drawMorphing();

	// // noLoop() removed for animation
}

function 	drawBack() {
	push();
	strokeWeight(1);

	// some rotation
	push()
	translate(width*0.5, height*0.5);
	rotate(frameCount * 0.01);
	translate(-width*0.5, -height*0.5);

	// dark blue line in the back 
	stroke(0,0,64)
	for (let i = -100; i < 100; i += 10) {
		const off = frameCount % 12;
		// line(0, i * 12 + off, width, i * i + off * 1.5)
		line(0, i * 0.5, width, i * 2)
	}
	pop();

	// radial line / star rays in the back
	const num = 120;
	const ang = frameCount * 0.01214;
	const rad = max(width, height) * 0.1;
	const cx = cos(ang) * rad;
	const cy = sin(ang) * rad;
	const lineLen = max(width, height) * 1.6;
	push();
	translate(cx - rad * 1.1, cy - rad * 1.1)
	rotate(frameCount*0.0052);
	for (let i = 0; i < num; i++) {
		stroke(255, 100 * noise(frameCount * 0.134 + i * 0.124))
		line(0, 0, lineLen, 0)
		rotate(TWO_PI / num);
	}
	pop();



	pop();
}


function drawCurrentState() {
	const cIndex = floor(frameCount/morphFrames) % morph.length;    // morph index
	const nIndex = (cIndex + 1) % morph.length;                     // next index   
	const p2maxNum = max(morph[cIndex].length, morph[nIndex].length); // min length of points of current  and next morph index
	const mProgress = getMorphProgress(); // 0..1 progress between morphing

	// console.log(">" + morph.length + ", " + cIndex);
	strokeWeight(4);

	// draw current state
	let colCurM = color(hbCol[cIndex]);
	stroke(red(window.color(colCurM)),green(window.color(colCurM)),blue(window.color(colCurM)), 255 - 255 * easeInOutElastic(mProgress));
	for (let p of morph[cIndex]) {
		point(p.x, p.y);
	}
}

function drawNextState() {
	var cIndex = floor(frameCount/morphFrames) % morph.length;    // morph index
	var nIndex = (cIndex + 1) % morph.length;                     // next index   
	var p2maxNum = max(morph[cIndex].length, morph[nIndex].length); // min length of points of current  and next morph index
	var mProgress = getMorphProgress(); // 0..1 progress between morphing

	// console.log(">" + morph.length + ", " + cIndex);
	strokeWeight(4);

	// draw next state
	let colNxtM = color(hbCol[nIndex]);
	stroke(red(window.color(colNxtM)),green(window.color(colNxtM)),blue(window.color(colNxtM)), 255 * easeInOutElastic(mProgress));
	for (let p of morph[nIndex]) {
		point(p.x, p.y);
	}
}

function drawMorphing() {
	var cIndex = floor(frameCount/morphFrames) % morph.length;    // morph index
	var nIndex = (cIndex + 1) % morph.length;                     // next index   
	var p2maxNum = max(morph[cIndex].length, morph[nIndex].length); // min length of points of current  and next morph index
	var mProgress = getMorphProgress(); // 0..1 progress between morphing

	// console.log(">" + morph.length + ", " + cIndex);
	strokeWeight(4);
	var colCurM = color(hbCol[cIndex]);
	var colNxtM = color(hbCol[nIndex]);

	// draw morphing between states
	const pr = easeInOutElastic(mProgress);
	const ps = easeInOutElastic(getMorphProgress(-1));
	for (let i = 0; i < p2maxNum; i++) {
		const ci = floor(i * morph[cIndex].length / p2maxNum);
		const ni = floor(i * morph[nIndex].length / p2maxNum);


		var x, y;
		// stroke(lerpColor(color(255, 128), lerpColor(colCurM, colNxtM, pr), sin(sin(mProgress * PI)*PI)));
		if (i % 2) {
			// every 2nd point will be morphed between the states
			x = lerp(morph[cIndex][ci].x, morph[nIndex][ni].x, pr);
			y = lerp(morph[cIndex][ci].y, morph[nIndex][ni].y, pr);
			strokeWeight(4);
			// stroke(lerpColor(lerpColor(colCurM, colNxtM, pr), color(255, 128), sin(pr * PI)));
			stroke(lerpColor(colCurM, colNxtM, pr));
			point(x, y)

		} else {
			// fade out to the left and fade in from the right

			const sclFactor = 1.25; // for movement in and out to work against the scaling

			x = lerp(morph[cIndex][ci].x, morph[cIndex][ci].x - width * sclFactor, pr);
			y = morph[cIndex][ci].y;
			let clr;

			// current state

			clr = lerpColor(colCurM, color(0), ps);
			stroke(red(window.color(clr)), green(window.color(clr)), blue(window.color(clr)), 255 * (1-mProgress*2)); // 128
			strokeWeight(3);
			point(x, y)
			if (i > 0) {
				// const f = (floor(y) % 2) * 2 - 1; // when using it below with f*width getting slooooow
				// const xl = lerp(morph[cIndex][ci].x, morph[cIndex][ci].x - f * width, ps);
				let xl = lerp(morph[cIndex][ci].x, morph[cIndex][ci].x - width, ps);
				if (floor(y) % 2) xl = lerp(morph[cIndex][ci].x, morph[cIndex][ci].x + width, ps);
				strokeWeight(1);
				line(x, y, xl, y)
			}

			// next state
			x = lerp(morph[nIndex][ni].x + width * sclFactor, morph[nIndex][ni].x, pr);
			y = morph[nIndex][ni].y;
			clr = lerpColor(color(0), colNxtM, pr);
			stroke(red(window.color(clr)), green(window.color(clr)), blue(window.color(clr)), 255 * mProgress); // 128
			strokeWeight(3);
			point(x, y)
			if (i > 0) {
				// const xr = lerp(morph[nIndex][ni].x + width, morph[nIndex][ni].x, ps);
				let xr = lerp(morph[nIndex][ni].x + width, morph[nIndex][ni].x, ps);
				if (floor(y) % 2) lerp(morph[nIndex][ni].x - width, morph[nIndex][ni].x, ps);
				strokeWeight(1);
				line(x, y, xr, y)
			}
		}
		// point(x, y)
	}
}


// generating symbols
function generateHeart(r) {
	push();
	noStroke()
	// strokeWeight(2);
	fill(192, 8, 32, 128);

	beginShape();
	for (let t = 0; t < TWO_PI; t += 0.1) {
		var x = 16 * sin(t) * sin(t) * sin(t);
		var y = 13 * cos(t) - 5 * cos(2 * t) - 2 * cos(3 * t) - cos(4 * t)
		x *= r / 16
		y *= r / -16
		vertex(x, y);
	}
	endShape(CLOSE);
	pop();
}

// https://easings.net/#easeInOutElastic
function easeInOutElastic(x) {
	const c5 = (2 * Math.PI) / 4.5;

	return x === 0
		? 0
		: x === 1
		? 1
		: x < 0.5
		? -(Math.pow(2, 20 * x - 10) * Math.sin((20 * x - 11.125) * c5)) / 2
		: (Math.pow(2, -20 * x + 10) * Math.sin((20 * x - 11.125) * c5)) / 2 + 1;
}
